package live.linghe.privateinput;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.util.*;import org.json.*;
/** File/algorithm tests only: no Context, UI, installed-app data or network. */
public final class CliPersonalCheck {
 interface Work{void run()throws Exception;}
 static void require(boolean b,String message){if(!b)throw new AssertionError(message);}
 static void rejects(Work work)throws Exception{boolean failed=false;try{work.run();}catch(Exception expected){failed=true;}require(failed,"invalid operation rejected");}
 public static void main(String[] args)throws Exception{
  File base=new File(args[0]);require(!base.exists()&&base.mkdirs(),"fresh shell-owned fixture");int passed=0;Set<String> syllables=new HashSet<>(Arrays.asList("ni","hao","mi"));
  require(PersonalLexicon.normalize(" NI\u00a0'\tHAO ").equals("ni hao"),"Unicode spacing normalization on Android");passed++;
  PersonalLexicon store=new PersonalLexicon(new File(base,"main"));PersonalLexicon.Entry entry=PersonalLexicon.Entry.create("word","拟好","ni hao");store.upsert(entry,syllables);String before=store.load().encode();rejects(()->store.upsert(PersonalLexicon.Entry.create("word","拟好","ni hao"),syllables));require(store.load().encode().equals(before),"duplicate entry atomic");passed++;
  store.remove(entry.id);store.merge(before);require(store.load().entries.isEmpty(),"stale archive cannot resurrect deletion");store.upsert(entry,syllables);require(store.load().entries.size()==1,"explicit restore works");passed++;
  PersonalLexicon peer=new PersonalLexicon(new File(base,"peer"));peer.merge(before);PersonalLexicon.Entry edited=new PersonalLexicon.Entry(entry.id,"word","新词条","ni hao");peer.upsert(edited,syllables);PersonalLexicon local=new PersonalLexicon(new File(base,"local"));local.merge(before);local.remove(entry.id);String deleted=local.load().encode(),updated=peer.load().encode();local.merge(updated);peer.merge(deleted);require(local.load().entries.isEmpty()&&peer.load().entries.isEmpty(),"concurrent delete wins both merge orders");passed++;
  String current=store.load().encode();File currentFile=new File(base,"main/personal-lexicon-v1.json");long stamp=1700000000000L;Files.setLastModifiedTime(currentFile.toPath(),java.nio.file.attribute.FileTime.fromMillis(stamp));store.merge(current);store.upsert(entry,syllables);require(currentFile.lastModified()==stamp,"unchanged imports and saves preserve file mtime");passed++;
  byte[] damaged="damaged".getBytes(StandardCharsets.UTF_8);Files.write(currentFile.toPath(),damaged);rejects(store::load);rejects(()->store.upsert(edited,syllables));require(Arrays.equals(Files.readAllBytes(currentFile.toPath()),damaged),"damaged archive retained");passed++;
  String fixture=new String(Files.readAllBytes(Paths.get(args[1])),StandardCharsets.UTF_8);PersonalLexicon.Snapshot cross=PersonalLexicon.decode(fixture);require(cross.entries.size()==3&&cross.removed().size()==1,"Apple fixture roundtrip");require(cross.matches("64426",true).size()==2&&cross.matches("ni'426",true).get(0).text.equals("拟好"),"ambiguous nine-key matching protects explicit syllables");Files.write(Paths.get(args[2]),cross.encode().getBytes(StandardCharsets.UTF_8));passed++;
  JSONObject lower=new JSONObject(fixture),upper=new JSONObject(fixture);String id="AAAAAAAA-AAAA-AAAA-AAAA-AAAAAAAAAAAA";for(JSONObject obj:new JSONObject[]{lower,upper}){String device=obj==lower?"aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa":"AAAAAAAA-AAAA-AAAA-AAAA-AAAAAAAAAAAA",text=obj==lower?"小写设备排序":"大写设备排序";JSONObject row=obj.getJSONObject("synchronization").getJSONObject("records").getJSONObject(id);row.getJSONObject("revision").put("device",device);row.getJSONObject("entry").put("text",text);obj.getJSONArray("entries").getJSONObject(0).put("text",text);}PersonalLexicon casing=new PersonalLexicon(new File(base,"case"));casing.merge(upper.toString());casing.merge(lower.toString());require(casing.load().entries.get(0).text.equals("小写设备排序"),"revision strings preserve lexical casing");passed++;
  rejects(()->PersonalLexicon.Entry.create("phrase","\u00a0","bb").validate(null));rejects(()->PersonalLexicon.Entry.create("phrase","bad\u202etext","bb").validate(null));JSONObject malformed=new JSONObject(fixture);malformed.getJSONArray("entries").getJSONObject(0).put("text",JSONObject.NULL);rejects(()->PersonalLexicon.decode(malformed.toString()));passed++;
  System.out.println("PASS "+passed+" Android-runtime CLI contract checks; UI acceptance remains separate");
 }
}
